head.script:
scwin.vScrenID = "popup_roadZipcode.xml";

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
	scwin.param = $c.data.getParameter();

};

// WebSquare 컴포넌트 이벤트 함수
/// EVENT ///

/**
 * 검색조건 변경
 */
scwin.rd_searchType_onviewchange = function (info) {
    const type = info.value;

    scwin.searchResult(false); //검색 초기화
    dma_Req.setEmptyValue(); //입력 초기화
    dma_Req.set("searchType", type);

    if(type === "1") {
        //검색조건
        grp_search1.show("");
        grp_search2.hide();
        grp_search3_1.hide();
        grp_search3_2.hide();

        //안내문구
        grp_info1.show("");
        grp_info2.hide();
        grp_info3.hide();

        //조회버튼
        btn_search.show("");
    } else if(type === "2") {
        //검색조건
        grp_search1.hide();
        grp_search2.show("");
        grp_search3_1.hide();
        grp_search3_2.hide();

        //안내문구
        grp_info1.hide();
        grp_info2.show("");
        grp_info3.hide();

        //조회버튼
        btn_search.show("");

    } else if(type === "3") {
        //검색조건
        grp_search1.hide();
        grp_search2.hide();
        grp_search3_1.show("");
        grp_search3_2.show("");

        //안내문구
        grp_info1.hide();
        grp_info2.hide();
        grp_info3.show("");

        //조회버튼
        btn_search.hide();
    }

};

/**
 * 조회 버튼 클릭
 */
scwin.btn_search_onclick = function (e) {
    let type = rd_searchType.getValue();
    if(scwin.checkValues(type)) {
	    const sbmOptions = {
	        id : "sbm_SelectRoadZip",
	        action : "/api/discls/common/popup/misc/zipcd/select-list",
	        method : "get",
	        ref : "dma_Req",
	        target : "dlt_AddrListRes=body",
	        submitDoneHandler : scwin.sbm_SelectRoadZip_submitdone,
	        gridview : "grd_Grid",
	        isProcessMsg : false
	    };
	    $c.sbm.executeDynamic(sbmOptions);

    } else {
        if(type === "1") {
            ipt_raodNm1.focus();
        } else if(type === "2") {
            ipt_bldgNo.focus();
        }
    }
};

/**
 * 직접입력 확인 버튼 클릭
 */
scwin.btn_confirm_onclick = function (e) {
	scwin.otherZipCodeChk();
};

/**
 * 닫기 버튼 클릭
 */
scwin.btn_cancel_onclick = function () {
    $c.win.closePopup();
};

/**
 * row 선택
 */
scwin.grd_Grid_oncellclick = function (rowIndex, columnIndex, columnId) {
	let rowData = dlt_AddrListRes.getRowJSON(rowIndex);
    if(rowData && rowData.zipCd && rowData.roadAddr) {
        scwin.setZipCodePop(rowData.zipCd, rowData.roadAddr);
    }
};

// 일반 함수
/// SUBMISSION ///
scwin.sbm_SelectRoadZip_submitdone = function (e) {
    const res = e.responseJSON;
    if(res.body && res.body.length > 0) {
        scwin.searchResult(true);
        scwin.fmtAddr(res.body);

    } else {
        scwin.searchResult(false);        
    }
};

/// FUNCTION ///

/**
 * row에 표시되는 주소 컬럼 포맷
 */
scwin.fmtAddr = function (resList) {
    for (let i = 0; i < resList.length; i++) {
        let item = resList[i];
        let addr = "<span class='txt_blue'>"+item.roadAddr+"</span>";
        addr += "</br>";
        addr += "<span style='padding: 0 4px;'> "+item.jibunAddr+"</span>";

        dlt_AddrListRes.setCellData(i, "displayAddr", addr);
    }
};

/**
 * 검색결과 표시
 */
scwin.searchResult = function (isResult) {
    if(isResult) {
        grp_zipLoad.show("");
        grp_resMsgBox.hide();

    } else {
        txt_message.setValue("조회 내역이 없습니다.");
        grp_zipLoad.hide();
        grp_resMsgBox.show("");
    }
};

/**
 * 조회 필수값 검증
 */
scwin.checkValues = function (type) {
    if(type === "1") { //도로명 검색
        let roadNm = ipt_raodNm1.getValue();
        let bldgNo = ipt_bldgNo.getValue();
        if(!roadNm) {
            alert ('검색할 도로명을 입력해 주세요.');
            return false;
        } else if(roadNm.length < 2) {
            alert('도로명은 두글자 이상 입력되어야 합니다.');
            return false;
        } else if(scwin.specialWord(roadNm) || scwin.specialWord(bldgNo)) {
            alert('%는 사용 할 수 없습니다.');
            return false;
        } else {
            return true;
        }

    } else if(type === "2") { //건물명 검색
        let roadNm = ipt_raodNm2.getValue();
        let bldgNm = ipt_bldgNm.getValue();
        if(!bldgNm) {
            alert('검색할 건물명을 입력해 주세요.');
            return false;
        } else if(bldgNm.length < 2) {
            alert('건물명은 두글자 이상 입력되어야 합니다.');
            return false;
        } else if(scwin.specialWord(bldgNm) || scwin.specialWord(roadNm)) {
            alert('%는 사용 할 수 없습니다.');
            return false;
        } else {
            return true;
        }

    } else {
        alert("검색조건을 선택하세요.");
        return false;
    }
};

/**
 * 특수문자(%) 사용 검증 - 전체조회 방지
 */
scwin.specialWord = function (str) {
    let reg = /%/;
    if (str === null || str === ""){
        return false;
    }
    if(reg.test(str)){
        return true;	
    }
};

/**
 * 직접입력 입력값 검증
 */
scwin.otherZipCodeChk = function () {
    let zipNo = ipt_zipCode.getValue();
    let addr = ipt_addr.getValue();
    if(!zipNo) {
        alert("우편번호를 입력해 주세요.");
        ipt_zipCode.focus();
        return;
    }

    if(/[^0123456789]/g.test(zipNo)) {

        if(zipNo !== "-") {
            alert("우편번호는 숫자 또는 -만 가능합니다.");
            ipt_zipCode.focus();
            return;
        }
    }

    if(!addr) {
        alert("주소를 입력해 주세요.");
        ipt_addr.focus();
        return;
    }

    scwin.setZipCodePop(zipNo, addr);
};

/**
 * 데이터 콜백(팝업 닫고 파라미터 전달)
 */
scwin.setZipCodePop = function (zipNo, addr) {
    $c.win.closePopup({"zipNo":zipNo, "addr":addr, "req": scwin.param.data}, scwin.param.callbackFn);
};
